"""Bounded GMRI research-loop transitions, independently constrained from model advice.

A Laya judgment may propose whether to continue, change course, or request review.
Deterministic integrity, authority, budget, and evidence gates always take priority.
This module does not invoke or authenticate a Laya model: OMP must acquire and log
an actual Laya verdict through a verified installed integration.
"""
from __future__ import annotations

from typing import Any

MIN_CONFIDENCE = 0.75
LAYA_CHOICES = {'continue', 'change_strategy', 'request_review', 'stop', 'escalate'}


def _valid_laya(advice: Any) -> bool:
    if not isinstance(advice, dict) or advice.get('choice') not in LAYA_CHOICES:
        return False
    conf = advice.get('answer_confidence')
    if type(conf) not in (int, float) or not 0 <= conf <= 1 or conf < MIN_CONFIDENCE:
        return False
    model = advice.get('model')
    if not isinstance(model, str) or not any(part.lower().startswith('laya') for part in model.replace('-', '/').split('/')):
        return False
    refs = advice.get('evidence_refs')
    if not isinstance(refs, list) or not refs or any(not isinstance(x, str) or not x.strip() for x in refs):
        return False
    return True


def evaluate(state: dict, laya_advice: dict | None = None) -> dict:
    """Return a structured loop action; never execute the action itself.

    STOP_VERIFIED pertains only to the *bounded work order*. Entire-research
    completion requires the separately executed 18-deliverable/84-question
    artifact audit and independent substantive review.
    """
    if not isinstance(state, dict):
        raise ValueError('state must be a dict')
    for key in ('iteration', 'blocking_defects', 'budget_remaining_units',
                'consecutive_same_remedy_failures', 'distinct_strategies_failed'):
        if type(state.get(key)) is not int or state[key] < 0:
            raise ValueError(f'{key} must be nonnegative integer')
    for key in ('source_integrity_verified', 'deliverables_verified',
                'requirements_coverage_verified', 'evidence_hashes_verified',
                'authority_blocked', 'stalled'):
        if type(state.get(key)) is not bool:
            raise ValueError(f'{key} must be boolean')
    tests = state.get('tests')
    if not isinstance(tests, list):
        raise ValueError('tests must be list')
    review = state.get('review')
    if not isinstance(review, dict):
        raise ValueError('review must be object')
    valid = _valid_laya(laya_advice)
    result = {
        'work_order_id': state.get('work_order_id'),
        'iteration': state['iteration'],
        'action': 'CONTINUE',
        'completion_claim_allowed': False,
        'research_completion_claim_allowed': False,
        'decision_source': 'DETERMINISTIC_POLICY',
        'reason': 'Work is incomplete; continue with the next evidenced action.',
        'laya_verdict': laya_advice['choice'] if valid else None,
        'laya_model': laya_advice['model'] if valid else None,
        'laya_evidence_refs': laya_advice['evidence_refs'] if valid else [],
        'laya_note': 'Laya provides typed loop advice, not authority to certify completion, change GMRI scope or approve release.',
    }

    def action(name: str, reason: str, verified: bool = False,
               source: str = 'DETERMINISTIC_POLICY') -> dict:
        result.update(action=name, reason=reason, completion_claim_allowed=verified,
                      decision_source=source)
        return result

    # Hard rules always precede every probabilistic judgment.
    if not state['source_integrity_verified']:
        return action('PAUSE_INTEGRITY', 'Authoritative source integrity is not verified.')
    if state['authority_blocked']:
        return action('ESCALATE_AUTHORITY', 'An actual operator authority boundary was encountered.')
    if state['budget_remaining_units'] == 0:
        return action('PAUSE_RESOURCE_BUDGET', 'The separately configured loop budget is exhausted.')
    if state['distinct_strategies_failed'] >= 3:
        return action('PAUSE_UNRESOLVED', 'Three distinct strategies failed. Preserve evidence; do not burn more resources.')
    if state['consecutive_same_remedy_failures'] >= 2:
        return action('CHANGE_STRATEGY', 'Two attempts at the same remedy failed; repeating it is not forward progress.')

    complete = (state['deliverables_verified'] and state['requirements_coverage_verified'] and
                state['evidence_hashes_verified'] and state['blocking_defects'] == 0 and bool(tests) and
                all(isinstance(t, dict) and t.get('status') == 'PASS' and t.get('evidence_ref') for t in tests))
    if complete:
        if (review.get('status') == 'PASS' and review.get('reviewer_id') and
                review.get('reviewer_id') != review.get('author_id') and review.get('evidence_ref')):
            return action('STOP_VERIFIED', 'Bounded work-order evidence and distinct reviewer PASS are recorded.', True)
        return action('REQUEST_INDEPENDENT_REVIEW', 'Work-order checks passed; independent reviewer evidence is missing.')

    # Laya guides loop transitions without becoming a proof oracle.
    if valid:
        source = 'LAYA_ADVISORY_POLICY_ENFORCED'
        choice = laya_advice['choice']
        if choice == 'stop':
            return action('REQUEST_INDEPENDENT_REVIEW',
                          'Laya proposed stopping, but work-order completion gates are not satisfied.', source=source)
        if choice == 'request_review':
            return action('REQUEST_INDEPENDENT_REVIEW',
                          'Laya requested a held-out examination, not a PASS verdict.', source=source)
        if choice == 'escalate' and state['stalled']:
            return action('ESCALATE_REVIEW', 'Laya identified unresolved stalled work; preserve work and request independent diagnosis.', source=source)
        if choice == 'change_strategy' and state['stalled']:
            return action('CHANGE_STRATEGY', 'Laya requested a new strategy for independently evidenced stalled work.', source=source)
        if choice == 'continue' and not state['stalled']:
            return action('CONTINUE', 'Laya supported continuing independently progressing work.', source=source)
    if state['stalled']:
        return action('PAUSE_SUPERVISION_UNAVAILABLE',
                      'A stalled loop has no valid Laya-supported transition; no LLM-only strategy/stop decision.')
    return result
