#!/usr/bin/env python3
"""Record a bounded GMRI loop action from actual evidence and optional Laya advice.

Reads JSON files only. Does not call models, run arbitrary tools, or mutate research
artifacts. The journal receives a single action receipt per invocation.
"""
from __future__ import annotations

import argparse
from datetime import datetime, timezone
import json
import os
from pathlib import Path
import sys
import tempfile

from loop_policy import evaluate


def read_json(path: Path, missing_ok: bool = False):
    if missing_ok and not path.exists():
        return None
    with path.open(encoding='utf-8') as handle:
        return json.load(handle)


def atomic_json(path: Path, data: dict):
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp = tempfile.mkstemp(dir=str(path.parent), prefix='.loop-decision-', suffix='.tmp')
    try:
        with os.fdopen(fd, 'w', encoding='utf-8') as handle:
            json.dump(data, handle, indent=2, ensure_ascii=False)
            handle.write('\n')
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(tmp, path)
    finally:
        if os.path.exists(tmp):
            os.unlink(tmp)


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--state', type=Path, required=True, help='actual bounded work-order state JSON')
    parser.add_argument('--laya', type=Path, help='optional actual Laya decision JSON, captured through verified OMP integration')
    parser.add_argument('--output', type=Path, required=True, help='machine-readable transition result')
    parser.add_argument('--journal', type=Path, help='append-only JSONL decision receipts')
    parser.add_argument('--research-root', type=Path, help='optional complete research artifact folder for final audit')
    parser.add_argument('--contract', type=Path, help='research audit contract, required with --research-root')
    args = parser.parse_args(argv)
    if bool(args.research_root) != bool(args.contract):
        parser.error('--research-root and --contract must be supplied together')
    try:
        state = read_json(args.state)
        advice = read_json(args.laya, missing_ok=True) if args.laya else None
        decision = evaluate(state, advice)
        decision['recorded_at_utc'] = datetime.now(timezone.utc).isoformat()
        # Work-order completion never automatically means entire directive completion.
        # Structural audit is run against ACTUAL output files, not model's boolean claims.
        if args.research_root and args.contract:
            from audit_research import audit
            contract = read_json(args.contract)
            status = audit(args.research_root, contract, source_dir=args.contract.resolve().parent)
            decision['research_audit'] = status
            decision['research_completion_claim_allowed'] = (
                decision['action'] == 'STOP_VERIFIED' and status['structurally_complete'])
        atomic_json(args.output, decision)
        if args.journal:
            args.journal.parent.mkdir(parents=True, exist_ok=True)
            # This is an operator-workspace decision log, not a concurrency-safe DB.
            with args.journal.open('a', encoding='utf-8') as handle:
                handle.write(json.dumps({k: v for k, v in decision.items() if k != 'research_audit'}, ensure_ascii=False) + '\n')
        print(json.dumps(decision, ensure_ascii=False))
        return 0
    except (ValueError, OSError, TypeError, KeyError, json.JSONDecodeError) as exc:
        print(f'LOOP SUPERVISOR ERROR: {exc}', file=sys.stderr)
        return 2


if __name__ == '__main__':
    raise SystemExit(main())
