#!/usr/bin/env python3
"""Discover, repair, or user-scope install a real local Laya judge for GMRI OMP.

No Proxmox mutations. Always attempt reuse before fetching. Does not install or
assume a Windows .cmd launcher on macOS/Linux. Project-owned MCP configuration
is backed up before edits. No automatic external model/LLM substitutions.
"""
from __future__ import annotations

import argparse
import datetime
import json
import os
from pathlib import Path
import shutil
import subprocess
import sys
import time
import urllib.request

ROOT = Path(__file__).resolve().parents[1]
UPSTREAM = 'https://github.com/F0Rextasy/omp-laya-judge.git'
DEFAULT_ENDPOINTS = ('http://127.0.0.1:3777', 'http://127.0.0.1:8100')


def _local_url(url: str) -> bool:
    from urllib.parse import urlparse
    p = urlparse(url)
    return p.scheme == 'http' and p.hostname in ('127.0.0.1', 'localhost', '::1') and p.port is not None


def probe(url: str, timeout: float = 2) -> dict | None:
    if not _local_url(url):
        return None
    try:
        opener=urllib.request.build_opener(urllib.request.ProxyHandler({}))
        with opener.open(url.rstrip('/')+'/info',timeout=timeout) as r:
            return json.loads(r.read(10000).decode())
    except (OSError,ValueError,TimeoutError):
        return None


def validate_info(info):
    if not isinstance(info,dict):
        return False,'No JSON status returned from local Laya sidecar'
    if info.get('backend')!='laya' or not str(info.get('model','')).startswith('laya/'):
        return False,'Endpoint does not identify a Laya decision-model backend'
    if info.get('startup_error'):
        return False,'Sidecar checkpoint load failed: '+str(info['startup_error'])
    if info.get('loaded') is not True:
        return False,'Laya endpoint exists but model is not yet loaded'
    return True,'Real local Laya sidecar is loaded'


def choose_existing_endpoint(urls,probe_fn=probe):
    for url in urls:
        info=probe_fn(url)
        if validate_info(info)[0]:
            return url,info
    return None,None


def check_disk_space(free_bytes: int,minimum: int=2_000_000_000):
    if free_bytes<minimum:
        return False,f'Only {free_bytes/1e9:.2f} GB free space, below {minimum/1e9:.2f} GB for a new model installation; choose an existing Laya endpoint or another authorized volume'
    return True,f'{free_bytes/1e9:.2f} GB available'


def _backed_up_write(path:Path, data:dict, project_root:Path):
    serialized=json.dumps(data,indent=2,ensure_ascii=False)+'\n'
    if path.exists() and path.read_text()==serialized:
        return False
    if path.exists():
        backupdir=project_root/'.gmri-local'/'backups'
        backupdir.mkdir(parents=True,exist_ok=True)
        stamp=datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')
        (backupdir/f'mcp-{stamp}.json').write_bytes(path.read_bytes())
    path.parent.mkdir(parents=True,exist_ok=True)
    tmp=path.with_suffix('.json.tmp')
    tmp.write_text(serialized)
    os.replace(tmp,path)
    return True


def update_omp_mcp(project_root:Path,python:Path,bridge:Path,endpoint:str):
    if not _local_url(endpoint):
        raise ValueError('Only localhost Laya sidecar URLs are accepted; use a user-managed local tunnel for remote inference')
    dest=project_root/'.omp'/'mcp.json'
    config=json.loads(dest.read_text()) if dest.exists() else {}
    if not isinstance(config,dict) or not isinstance(config.get('mcpServers',{}),dict):
        raise ValueError('Existing OMP project MCP config is not a valid object; no overwrite performed')
    servers=config.setdefault('mcpServers',{})
    servers['gmri-laya-judge']={
        'type':'stdio','command':str(python),'args':[str(bridge)],
        'cwd':str(bridge.parent),'timeout':600000,
        'description':'GMRI local typed-decision judge (real Laya sidecar)',
        'env':{'PYTHONUNBUFFERED':'1','LAYA_SIDECAR_URL':endpoint}}
    return _backed_up_write(dest,config,project_root)


def _run(cmd,**kwargs):
    return subprocess.run([str(v) for v in cmd],check=True,text=True,**kwargs)


def _ensure_repo(repo:Path,apply:bool):
    if (repo/'server'/'bridge.py').exists() and (repo/'server'/'sidecar.py').exists():
        return 'reuse cached upstream integration'
    if not apply:
        return 'would fetch upstream OMP-Laya integration'
    if repo.exists() and any(repo.iterdir()):
        raise RuntimeError(f'Existing {repo} is not a verified judge checkout; preserve it and diagnose rather than overwrite')
    if not shutil.which('git'):
        raise RuntimeError('git unavailable, cannot fetch maintained upstream judge source')
    repo.parent.mkdir(parents=True,exist_ok=True)
    _run(['git','clone','--depth','1',UPSTREAM,str(repo)])
    if not (repo/'server'/'bridge.py').exists():
        raise RuntimeError('Upstream clone missing expected MCP bridge')
    return 'fetched source from upstream'


def _ensure_python_env(envdir:Path,repo:Path,apply:bool,bridge_only:bool):
    vpy=envdir/('Scripts/python.exe' if sys.platform=='win32' else 'bin/python')
    if vpy.exists():
        if subprocess.run([str(vpy),'-I','-c','import mcp;import laya' if not bridge_only else 'import mcp'],capture_output=True).returncode==0:
            return vpy,'reused working Python environment'
    if not apply:
        return vpy,'would install user-scoped Python environment'
    if not vpy.exists():
        _run([sys.executable,'-m','venv',str(envdir)])
    _run([vpy,'-m','pip','install','--disable-pip-version-check',
          'mcp<2'] if bridge_only else
         [vpy,'-m','pip','install','--disable-pip-version-check','-r',repo/'server'/'requirements.txt'])
    check='import mcp' if bridge_only else 'import mcp;import laya'
    _run([vpy,'-I','-c',check])
    return vpy,'verified dependencies in separate virtual environment'


def _launch_sidecar(python:Path,source:Path,port:int,logpath:Path):
    logpath.parent.mkdir(parents=True,exist_ok=True)
    env=os.environ.copy()
    env.update({'LAYA_MODELS':'english','LAYA_MODEL':'english',
                'HF_HUB_OFFLINE':'0','TRANSFORMERS_OFFLINE':'0','PYTHONUNBUFFERED':'1'})
    with logpath.open('ab') as log:
        p=subprocess.Popen([str(python),str(source/'server'/'sidecar.py'),'--port',str(port)],
                stdout=log,stderr=subprocess.STDOUT,cwd=str(source/'server'),
                start_new_session=True,env=env)
    return p.pid


def _wait_loaded(endpoint:str,timeout:float=300):
    until=time.monotonic()+timeout
    last=None
    while time.monotonic()<until:
        info=probe(endpoint,timeout=1.0)
        if info:
            last=info
            if validate_info(info)[0]:
                return info
            if info.get('startup_error'):
                raise RuntimeError(str(info['startup_error']))
        time.sleep(2)
    raise RuntimeError('Laya did not load within allotted startup time; status='+str(last))


def setup(project_root:Path=ROOT,apply:bool=False,wait_seconds:int=300):
    home=Path(os.environ.get('GMRI_LAYA_HOME',str(project_root/'.gmri-local'))).expanduser().resolve()
    repo=Path(os.environ.get('GMRI_LAYA_SOURCE',str(home/'laya-judge-src'))).expanduser().resolve()
    envdir=Path(os.environ.get('GMRI_LAYA_VENV',str(home/'laya-env'))).expanduser().resolve()
    endpoint_from_env=os.environ.get('LAYA_SIDECAR_URL')
    candidates=([endpoint_from_env] if endpoint_from_env else [])+list(DEFAULT_ENDPOINTS)
    candidates=list(dict.fromkeys(x for x in candidates if x and _local_url(x)))
    found,info=choose_existing_endpoint(candidates)
    status={'status':'READY' if found else 'SETUP_REQUIRED','endpoint':found,
            'model':info.get('model') if info else None,'actions':[],'source':str(repo)}
    # Use locally healthy model even when plugin integration is missing.
    selected=found or 'http://127.0.0.1:3777'
    if not found:
        for url in candidates:
            meta=probe(url)
            if meta and meta.get('backend')=='laya' and meta.get('startup_error'):
                status['actions'].append('Observed failed existing Laya sidecar at '+url+': '+str(meta['startup_error']))
    if not apply:
        status['actions'].append('Read-only discovery complete; use --apply to install/repair only if needed')
        return status
    status['actions'].append(_ensure_repo(repo,apply=True))
    if not found:
        # Reuse a known existing localhost sidecar first. Only install new weights if absent.
        if sys.version_info<(3,10):
            raise RuntimeError('Python 3.10+ required for Laya; OMP must select a supported local interpreter')
        home.mkdir(parents=True,exist_ok=True)
        free=shutil.disk_usage(home).free
        okay,detail=check_disk_space(free)
        status['actions'].append(detail)
        if not okay:
            raise RuntimeError('New local Laya installation needs adequate disk capacity. '+detail)
    python,desc=_ensure_python_env(envdir,repo,apply=True,bridge_only=bool(found))
    status['actions'].append(desc)
    if not found:
        # If an *existing* Laya process is bound but still loading, give it a chance.
        existing=probe(selected)
        if existing and existing.get('backend')=='laya' and not existing.get('startup_error'):
            status['actions'].append('Wait for pre-existing Laya sidecar startup')
        else:
            port=int(selected.rsplit(':',1)[1])
            pid=_launch_sidecar(python,repo,port,home/'laya-sidecar.log')
            status['actions'].append(f'Launched local Laya sidecar PID {pid}')
        info=_wait_loaded(selected,timeout=wait_seconds)
        status['model']=info.get('model')
    changed=update_omp_mcp(project_root,python,repo/'server'/'bridge.py',selected)
    status['actions'].append('Wrote/backed up project MCP configuration' if changed else 'Reused existing project MCP configuration')
    status['endpoint']=selected
    status['status']='READY'
    try:
        status['source_revision']=subprocess.check_output(['git','-C',str(repo),'rev-parse','HEAD'],text=True,stderr=subprocess.DEVNULL).strip()
    except (OSError,subprocess.CalledProcessError):
        status['source_revision']='unverified existing source; inspect before relying on it'
    return status


def main(argv=None):
    ap=argparse.ArgumentParser(description=__doc__)
    ap.add_argument('--apply',action='store_true',help='reuse/repair/download local Laya and configure OMP project MCP, preserving other plugins')
    ap.add_argument('--project',type=Path,default=ROOT)
    ap.add_argument('--wait-seconds',type=int,default=300)
    args=ap.parse_args(argv)
    try:
        outcome=setup(args.project.resolve(),args.apply,args.wait_seconds)
        print(json.dumps(outcome,indent=2))
        return 0 if outcome['status']=='READY' else 3
    except Exception as err:
        print(json.dumps({'status':'SETUP_FAILED','error':str(err),'next':'Preserve exact error; try existing Laya endpoint, appropriate GMRI storage, or alternate authorized local runtime; continue independent research work.'},indent=2),file=sys.stderr)
        return 2

if __name__=='__main__':raise SystemExit(main())
