#!/usr/bin/env python3
"""Actually request a typed local Laya verdict and run GMRI deterministic loop policy.

At each checkpoint: read real work-order state, auto-repair local Laya if absent,
make a real POST /judge, persist raw receipt and bound advice, then run the tested
supervisor. The research LLM never writes its own Laya judgment.
"""
from __future__ import annotations
import argparse
from datetime import datetime, timezone
import json
from pathlib import Path
import subprocess
import sys
import urllib.request

from laya_setup import ROOT, probe, setup, validate_info
from loop_supervisor import atomic_json


def loop_questions():
    return {'loop': {'type':'choice',
        'instructions':'For this research work order, choose the most defensible next step. Do not treat a model assertion as evidence of completion. Base choice only on recorded findings, defects, progress, reviewed evidence and repeated failures; do not change the approved objective.',
        'criteria':{
            'continue':'The current evidenced method is progressing and has a meaningful next step.',
            'change_strategy':'The present approach is stalled or repeating failure, and a distinct technical method should be evaluated.',
            'request_review':'There are material uncertain findings or work appears ready for independent evidence-based evaluation.',
            'stop':'The bounded work order appears to satisfy all its recorded requirements and should be sent for deterministic and independent closure checks.',
            'escalate':'A concrete persistent blocker merits independent technical diagnosis or a specific investigator authority decision.'}}}


def normalize_laya_response(state,payload):
    if not isinstance(payload,dict) or not str(payload.get('model','')).startswith('laya/'):
        raise ValueError('Real local Laya provenance was not returned')
    answer=(payload.get('answers') or {}).get('loop')
    if not isinstance(answer,dict) or answer.get('choice') not in loop_questions()['loop']['criteria']:
        raise ValueError('Laya answer omitted a valid typed loop choice')
    confidence=answer.get('answer_confidence')
    if confidence is None:
        probs=answer.get('probabilities')
        if isinstance(probs,dict): confidence=probs.get(answer['choice'])
    if type(confidence) not in (int,float) or not 0<=confidence<=1:
        raise ValueError('No actual answer confidence was returned by the Laya model')
    refs=list(dict.fromkeys([str(x) for x in (state.get('evidence_refs') or []) if x]+[
        str(x['evidence_ref']) for x in state.get('tests',[]) if isinstance(x,dict) and x.get('evidence_ref')]))
    return {'work_order_id':state['work_order_id'],'iteration':state['iteration'],
            'choice':answer['choice'],'answer_confidence':float(confidence),
            'model':payload['model'],'evidence_refs':refs,
            'rationale':'Independent typed loop choice over recorded state; see linked raw Laya response and deterministic decision receipt'}


def invoke(endpoint:str,state:dict,timeout=45):
    # Do not submit unbounded source documents or credentials to a model; only bounded work-order data.
    relevant={k:state.get(k) for k in ('work_order_id','iteration','stalled','blocking_defects',
        'consecutive_same_remedy_failures','distinct_strategies_failed','budget_remaining_units',
        'deliverables_verified','requirements_coverage_verified','tests','evidence_refs')}
    data=json.dumps({'state':json.dumps(relevant,ensure_ascii=False)[:12000],
                     'questions':loop_questions()}).encode()
    req=urllib.request.Request(endpoint+'/judge',data=data,headers={'Content-Type':'application/json'},method='POST')
    opener=urllib.request.build_opener(urllib.request.ProxyHandler({}))
    with opener.open(req,timeout=timeout) as r:
        return json.loads(r.read(200000).decode())


def run_checkpoint(state_path:Path,outdir:Path,auto_repair:bool=True,project_root:Path=ROOT):
    state=json.loads(state_path.read_text())
    if not isinstance(state,dict) or not state.get('work_order_id') or type(state.get('iteration')) is not int:
        raise ValueError('Checkpoint requires current work_order_id and integer iteration')
    outdir.mkdir(parents=True,exist_ok=True)
    receipt={'time':datetime.now(timezone.utc).isoformat(),'work_order_id':state['work_order_id'],
             'iteration':state['iteration'],'state_file':str(state_path),'laya_status':'UNKNOWN'}
    advice_path=outdir/'laya-advice.json'
    if advice_path.exists(): advice_path.unlink()  # Never reuse previous iteration's verdict.
    chosen=None
    try:
        status=setup(project_root,apply=auto_repair,wait_seconds=300)
        if status['status']!='READY': raise RuntimeError(str(status))
        chosen=status['endpoint']
        ready,reason=validate_info(probe(chosen))
        if not ready: raise RuntimeError(reason)
        raw=invoke(chosen,state)
